import React, { useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import ShareIcon from '@mui/icons-material/Share';
import ScheduleIcon from '@mui/icons-material/Schedule';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import ApiService from '../../services/api';
import { useSupplierCarbonScoresQuery } from '../../hooks/queries/usePlatformQueries';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { queryKeys } from '../../constants/queryKeys';
import useAppTranslation from '../../hooks/useAppTranslation';

type SupplierScoreRow = {
  vendor: string;
  scoreBand: string;
  intensityKgCo2ePerInr: number;
  tier1DataRatio: number;
  recommendation?: string;
};

type SupplierScoresPayload = {
  suppliers?: SupplierScoreRow[];
  summary?: {
    supplierCount?: number;
    tier1CoveragePct?: number;
  };
};

type ScheduledReportRow = {
  _id: string;
  reportType?: string;
  format?: string;
  frequency?: string;
  recipients?: string[];
  enabled?: boolean;
  nextRunAt?: string;
  lastRunAt?: string;
  lastStatus?: string;
};

export type ReportingPlatformPanelProps = {
  period?: string;
  reportType?: string;
  readinessLevel?: string | null;
  totalKgCo2e?: number;
};

const ReportingPlatformPanel: React.FC<ReportingPlatformPanelProps> = ({
  period = 'annual',
  reportType = 'brsr',
  readinessLevel = 'prep_draft',
  totalKgCo2e = 0,
}) => {
  const { t, locale, setLocale } = useAppTranslation();
  const queryClient = useQueryClient();
  const supplierQuery = useSupplierCarbonScoresQuery(10);
  const schedulesQuery = useQuery({
    queryKey: queryKeys.platform.scheduledReports,
    queryFn: async () => {
      const response = await ApiService.getScheduledReports();
      return ((response as { data?: unknown[] })?.data || []) as Record<string, unknown>[];
    },
    staleTime: 60 * 1000,
  });

  const [scheduleFrequency, setScheduleFrequency] = useState('weekly');
  const [scheduleEmail, setScheduleEmail] = useState('');
  const [scheduleSaving, setScheduleSaving] = useState(false);
  const [whatsappLoading, setWhatsappLoading] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const schedules = (schedulesQuery.data || []) as ScheduledReportRow[];
  const [scheduleActionId, setScheduleActionId] = useState<string | null>(null);

  const supplierData = (supplierQuery.data || null) as SupplierScoresPayload | null;
  const suppliers = supplierData?.suppliers || [];

  const handleWhatsAppShare = async () => {
    setWhatsappLoading(true);
    setError(null);
    setFeedback(null);
    try {
      const response = await ApiService.buildWhatsAppSharePayload({
        reportType,
        period,
        readinessLevel: readinessLevel || 'prep_draft',
        totalKgCo2e,
      });
      const payload = (response as { data?: { whatsappUrl?: string; enabled?: boolean } })?.data;
      if (!payload?.enabled) {
        setError('WhatsApp sharing is disabled on this environment.');
        return;
      }
      if (payload.whatsappUrl) {
        window.open(payload.whatsappUrl, '_blank', 'noopener,noreferrer');
        setFeedback('WhatsApp share opened — review the message before sending.');
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'WhatsApp share failed.');
    } finally {
      setWhatsappLoading(false);
    }
  };

  const handleCreateSchedule = async () => {
    setScheduleSaving(true);
    setError(null);
    setFeedback(null);
    try {
      const recipients = scheduleEmail.trim() ? [scheduleEmail.trim()] : undefined;
      await ApiService.createScheduledReport({
        reportType,
        format: 'pdf',
        frequency: scheduleFrequency,
        recipients,
        subject: `Scheduled ${reportType.toUpperCase()} report`,
      });
      await queryClient.invalidateQueries({ queryKey: queryKeys.platform.scheduledReports });
      setFeedback('Scheduled report delivery saved.');
      setScheduleEmail('');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to save schedule.');
    } finally {
      setScheduleSaving(false);
    }
  };

  const handleToggleSchedule = async (schedule: ScheduledReportRow) => {
    setScheduleActionId(schedule._id);
    setError(null);
    try {
      await ApiService.updateScheduledReport(schedule._id, { enabled: !schedule.enabled });
      await queryClient.invalidateQueries({ queryKey: queryKeys.platform.scheduledReports });
      setFeedback(schedule.enabled ? 'Schedule paused.' : 'Schedule resumed.');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to update schedule.');
    } finally {
      setScheduleActionId(null);
    }
  };

  const handleDeleteSchedule = async (scheduleId: string) => {
    setScheduleActionId(scheduleId);
    setError(null);
    try {
      await ApiService.deleteScheduledReport(scheduleId);
      await queryClient.invalidateQueries({ queryKey: queryKeys.platform.scheduledReports });
      setFeedback('Schedule removed.');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to delete schedule.');
    } finally {
      setScheduleActionId(null);
    }
  };

  const formatScheduleDate = (value?: string) => {
    if (!value) return '—';
    return new Date(value).toLocaleString('en-IN', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <Card variant="outlined" sx={{ mb: 3 }}>
      <CardContent>
        <Stack spacing={2}>
          <Box>
            <Stack direction="row" justifyContent="space-between" alignItems="flex-start" flexWrap="wrap" gap={1}>
              <Box>
                <Typography variant="subtitle1" fontWeight={700} gutterBottom>
                  {t('reporting.shareDelivery')}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 760 }}>
                  Share a draft summary with buyers, review supplier carbon scores, or schedule recurring PDF delivery.
                </Typography>
              </Box>
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <InputLabel>{t('common.language')}</InputLabel>
                <Select
                  value={locale}
                  label={t('common.language')}
                  onChange={(e) => setLocale(e.target.value as 'en' | 'hi')}
                >
                  <MenuItem value="en">English</MenuItem>
                  <MenuItem value="hi">हिंदी</MenuItem>
                </Select>
              </FormControl>
            </Stack>
          </Box>

          {feedback ? <Alert severity="success">{feedback}</Alert> : null}
          {error ? <Alert severity="error">{error}</Alert> : null}

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap>
            <Button
              variant="outlined"
              startIcon={whatsappLoading ? <CircularProgress size={16} /> : <ShareIcon />}
              disabled={whatsappLoading}
              onClick={() => void handleWhatsAppShare()}
            >
              {t('common.shareWhatsApp')}
            </Button>
          </Stack>

          <Box>
            <Typography variant="subtitle2" gutterBottom>
              Supplier carbon scores
            </Typography>
            {supplierQuery.isLoading ? (
              <CircularProgress size={20} />
            ) : suppliers.length === 0 ? (
              <Typography variant="body2" color="text.secondary">
                No supplier spend data yet — import purchases or register upstream suppliers.
              </Typography>
            ) : (
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Supplier</TableCell>
                      <TableCell>Band</TableCell>
                      <TableCell align="right">Intensity</TableCell>
                      <TableCell align="right">Tier-1 data</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {suppliers.slice(0, 5).map((row) => (
                      <TableRow key={row.vendor}>
                        <TableCell>{row.vendor}</TableCell>
                        <TableCell>
                          <Chip size="small" label={row.scoreBand} color={['A', 'B'].includes(row.scoreBand) ? 'success' : 'warning'} />
                        </TableCell>
                        <TableCell align="right">{row.intensityKgCo2ePerInr.toFixed(4)}</TableCell>
                        <TableCell align="right">{Math.round((row.tier1DataRatio || 0) * 100)}%</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )}
          </Box>

          <Box>
            <Typography variant="subtitle2" gutterBottom>
              Scheduled PDF delivery
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }} useFlexGap>
              <FormControl size="small" sx={{ minWidth: 140 }}>
                <InputLabel>Frequency</InputLabel>
                <Select
                  value={scheduleFrequency}
                  label="Frequency"
                  onChange={(e) => setScheduleFrequency(e.target.value)}
                >
                  <MenuItem value="daily">Daily</MenuItem>
                  <MenuItem value="weekly">Weekly</MenuItem>
                  <MenuItem value="monthly">Monthly</MenuItem>
                </Select>
              </FormControl>
              <TextField
                size="small"
                label="Recipient email (optional)"
                value={scheduleEmail}
                onChange={(e) => setScheduleEmail(e.target.value)}
                sx={{ minWidth: 220 }}
              />
              <Button
                variant="contained"
                startIcon={scheduleSaving ? <CircularProgress size={16} color="inherit" /> : <ScheduleIcon />}
                disabled={scheduleSaving}
                onClick={() => void handleCreateSchedule()}
              >
                Save schedule
              </Button>
            </Stack>
            {schedules.length > 0 ? (
              <TableContainer sx={{ mt: 1 }}>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Report</TableCell>
                      <TableCell>Frequency</TableCell>
                      <TableCell>Next run</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell align="right">Actions</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {schedules.map((schedule) => (
                      <TableRow key={schedule._id}>
                        <TableCell>{String(schedule.reportType || 'brsr').toUpperCase()} · {schedule.format || 'pdf'}</TableCell>
                        <TableCell>{schedule.frequency || 'weekly'}</TableCell>
                        <TableCell>{formatScheduleDate(schedule.nextRunAt)}</TableCell>
                        <TableCell>
                          <Chip
                            size="small"
                            label={schedule.enabled === false ? 'Paused' : schedule.lastStatus || 'Active'}
                            color={schedule.enabled === false ? 'default' : 'success'}
                          />
                        </TableCell>
                        <TableCell align="right">
                          <Stack direction="row" spacing={0.5} justifyContent="flex-end">
                            <Button
                              size="small"
                              disabled={scheduleActionId === schedule._id}
                              onClick={() => void handleToggleSchedule(schedule)}
                            >
                              {schedule.enabled === false ? 'Resume' : 'Pause'}
                            </Button>
                            <Button
                              size="small"
                              color="error"
                              startIcon={<DeleteOutlineIcon fontSize="small" />}
                              disabled={scheduleActionId === schedule._id}
                              onClick={() => void handleDeleteSchedule(schedule._id)}
                            >
                              Delete
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            ) : (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                No schedules yet — save one above to receive recurring PDF delivery.
              </Typography>
            )}
          </Box>
        </Stack>
      </CardContent>
    </Card>
  );
};

export default ReportingPlatformPanel;
